// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Phishable} from "../src/Phishable.sol";

contract InvMutTest is Test {
    Phishable c;
    function setUp() public { c = new Phishable(address(this)); }
    function testFuzz_property(uint256 amount, address recipient) public {
        vm.assume(recipient != address(c));
        vm.assume(amount > 0);
        vm.assume(recipient != address(0));
        vm.deal(address(c), amount);
        uint256 balBefore = address(c).balance;
        vm.prank(address(this));
        c.withdrawAll(recipient);
        assertTrue(address(c).balance == 0 && recipient.balance == balBefore);
    }
}
